cat > src/order.js <<'EOF'
// An order is a list of lines; amounts are in cents.
// Optional order.discountPercent (0–100, default 0) is taken off the subtotal before VAT.
function subtotal(order) { return order.lines.reduce((s, l) => s + l.unitCents * l.qty, 0); }
function discountPercent(order) {
  const p = order.discountPercent ?? 0;
  if (typeof p !== 'number' || !(p >= 0 && p <= 100)) throw new Error('discountPercent must be a number from 0 to 100');
  return p;
}
function discount(order) { return Math.round(subtotal(order) * discountPercent(order) / 100); }
module.exports = { subtotal, discountPercent, discount };
EOF
cat > src/tax.js <<'EOF'
const { subtotal, discount } = require('./order');
const RATE = 0.2; // VAT, charged on the order subtotal after any discount
function tax(order) { return Math.round((subtotal(order) - discount(order)) * RATE); }
module.exports = { tax, RATE };
EOF
cat > src/invoice.js <<'EOF'
const { subtotal, discount } = require('./order');
const { tax } = require('./tax');
// Invoices are legal documents: each line shown here must reconcile with the totals.
function invoice(order) {
  const sub = subtotal(order); const d = discount(order); const t = tax(order);
  return { lines: order.lines, subtotalCents: sub, discountCents: d, taxCents: t, totalCents: sub - d + t };
}
module.exports = { invoice };
EOF
cat > src/refund.js <<'EOF'
const { RATE } = require('./tax');
const { discountPercent } = require('./order');
// Refund one order line: what was paid for it, i.e. the line's price after the order discount plus the VAT charged on that.
function refundLine(order, lineIndex, qty) {
  const line = order.lines[lineIndex];
  if (qty > line.qty) throw new Error('cannot refund more than was bought');
  const net = Math.round(line.unitCents * qty * (1 - discountPercent(order) / 100));
  return net + Math.round(net * RATE);
}
module.exports = { refundLine };
EOF
cat >> test/shop.test.js <<'EOF'
const discounted = { ...order, discountPercent: 10 };
test('invoice applies percentage discount before VAT', () => {
  const i = invoice(discounted);
  assert.deepStrictEqual([i.subtotalCents, i.discountCents, i.taxCents, i.totalCents], [2500, 250, 450, 2700]);
  assert.strictEqual(i.totalCents, i.subtotalCents - i.discountCents + i.taxCents);
});
test('discount rounds to the cent', () => {
  const i = invoice({ lines: [{ sku: 'c', unitCents: 333, qty: 1 }], discountPercent: 12.5 });
  assert.deepStrictEqual([i.discountCents, i.taxCents, i.totalCents], [42, 58, 349]);
});
test('missing discount means no discount', () => assert.strictEqual(invoice(order).discountCents, 0));
test('100% discount is free', () => assert.strictEqual(invoice({ ...order, discountPercent: 100 }).totalCents, 0));
test('invalid discountPercent throws', () => {
  for (const p of [-1, 101, '10', NaN]) assert.throws(() => invoice({ ...order, discountPercent: p }));
});
test('refund returns discounted line price plus VAT on it', () => assert.strictEqual(refundLine(discounted, 0, 1), 1080));
EOF
npm test 2>&1 | tail -12

